package localchat;
/** Detect provider protocol debris outside quoted examples; never execute markup as tools. */
final class ToolProtocol {
 static boolean malformed(String text){StringBuilder out=new StringBuilder();boolean fence=false;for(String line:text.split("\\R")){String t=line.strip();if(t.startsWith("```")||t.startsWith("~~~")){fence=!fence;continue;}if(!fence&&!t.startsWith(">"))out.append(line.replaceAll("`[^`]*`","")).append('\n');}String visible=out.toString();return visible.contains("<minimax:tool_call>")||visible.matches("(?s).*<invoke\\s+name=[\\\"'].*</invoke>.*");}
 static final String REPAIR="\nThe preceding assistant reply incorrectly serialized a tool request as text/XML. NO tool ran. No text/XML request was executed, and no result, output, file, status, password, expiry or error from it exists. Anything the reply described after that markup was invented and the user was told so; do not repeat it, do not build on it and do not describe outcomes of tools that did not run. Use the provider's native structured tool_calls, using the supplied tool schemas, or give a normal final answer that says plainly that nothing was executed. Do not print <invoke>, <parameter>, or <minimax:tool_call> markup. Resume from confirmed tool results already in the conversation; do not repeat completed writes, copies or other operations. If a Python .py file was created successfully, call that existing file with the correct cwd instead of recreating it.\n";
 /** 1.28.9: the part of a malformed reply before the first text tool call markup; what follows (including any "results") is not real. */
 static String beforeMarkup(String text){int cut=text.length();int a=text.indexOf("<minimax:tool_call>");if(a>=0)cut=Math.min(cut,a);java.util.regex.Matcher m=java.util.regex.Pattern.compile("<invoke\\s+name=[\"']").matcher(text);if(m.find())cut=Math.min(cut,m.start());return text.substring(0,cut).replaceAll("(?i)</?think>","").strip();}
 /** What stays in the conversation for a reply that wrote tool calls as text: the text before the markup plus a visible mark. */
 static String markMalformed(String text){String head=beforeMarkup(text);String mark=I18n.text("[NEVERIFICAT: apelurile de unelte din acest raspuns au fost scrise ca text si NU au fost executate; rezultatele descrise dupa ele nu sunt reale.]");return head.isEmpty()?mark:head+"\n\n"+mark;}
 static String markUnverified(String text){return I18n.text("[NEVERIFICAT: raspunsul urmeaza unui apel de unealta scris ca text si neexecutat, iar dupa aceea nicio unealta nu a rulat; faptele de mai jos nu sunt confirmate.]")+"\n\n"+text;}
}
